/// url = 'https://genomde.de/fhir/StructureMap/EngineQuirkQ2bare'
/// name = 'EngineQuirkQ2bare'
/// title = 'Engine probe: fml-edit-safe quirk Q2 method call on an as-bound variable without parentheses - expected parse error'
/// status = 'draft'

uses "https://genomde.de/fhir/StructureDefinition/DatenkranzOncology" alias Datenkranz as source
uses "http://hl7.org/fhir/StructureDefinition/Patient" alias Patient as target

group main(source src : Datenkranz, target pat : Patient) {
  src.metaData as md then Md(md, pat) "md";
}

group Md(source md, target pat : Patient) {
  md.tanC as t -> pat.identifier as id, id.system = 'urn:q2:bare', id.value = t.substring(0, 8) "bare";
}
